<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {t as uiText} from '@/locales'
import {getManufacturingRelations,type ManufacturingRelation} from '@/api/modules/manufacturing'
import {holeTypeNames} from '@/utils/engineeringPlan'
const props=defineProps<{productLineId:number;phoneModelId?:number;holeType?:string;requireSharedMaterial?:boolean}>()
const emit=defineEmits<{close:[];selected:[ManufacturingRelation]}>()
const rows=ref<ManufacturingRelation[]>([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),error=ref('')
async function load(){loading.value=true;error.value='';try{const result=await getManufacturingRelations({productLineId:props.productLineId,phoneModelId:props.phoneModelId,keyword:keyword.value,page:page.value,size:20});rows.value=result.content;total.value=result.totalElements}catch(cause){error.value=cause instanceof Error?cause.message:'关系读取失败，请重试'}finally{loading.value=false}}
function matches(row:ManufacturingRelation){return row.status==='active'&&(!props.holeType||row.holeType===props.holeType)&&(!props.requireSharedMaterial||row.sharedMaterial)}
onMounted(load)
</script>
<template><el-dialog :model-value="true" :title="uiText('已确认的生产与模具关系')" width="min(820px,96vw)" append-to-body :close-on-click-modal="false" @close="emit('close')"><div class="relation-picker"><p>{{uiText('已保存关联，实际采用时重新核对')}}</p><div class="tools"><el-input v-model="keyword" :placeholder="uiText('搜索款式、制造编码或模具')" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">{{uiText('查询')}}</el-button></div><el-alert v-if="error" :title="uiText(error)" type="error" :closable="false"><el-button link @click="load">{{uiText('重试')}}</el-button></el-alert><div v-loading="loading" class="relation-results"><article v-for="row in rows" :key="row.id"><div><strong>{{row.moldName||row.styleName}} · {{uiText(holeTypeNames[row.holeType])}}</strong><p>{{row.businessPhone?.modelName}} · {{uiText('手机编码')}} {{row.businessPhone?.phoneModelCode}}</p><p>{{uiText('制造编码')}} {{row.manufacturingPhoneCode||uiText('独立物料待确认')}} · {{uiText('实物套')}} {{row.physicalCode||`ID #${row.moldSetId}`}}<template v-if="row.setNo"> · {{row.setNo}}</template> · {{row.sharedMaterial?uiText('共用生产物料'):uiText('仅共模，不共用成品')}}</p><small>{{uiText('结构说明')}}：{{row.structureDescription||'—'}}</small><small>{{row.moldEvidence}}</small><small v-if="!matches(row)">{{uiText('孔型或关系状态不符合本次规格，不能采用。')}}</small></div><el-button type="primary" :disabled="!matches(row)" @click="emit('selected',row)">{{uiText('采用此关系')}}</el-button></article><p v-if="!rows.length&&!loading">{{uiText('暂无已确认关系，请先由工程在手机资料的生产与模具关联中维护。')}}</p></div><el-pagination small layout="total,prev,pager,next" :total="total" :current-page="page" :page-size="20" @current-change="page=$event;load()"/></div><template #footer><el-button @click="emit('close')">{{uiText('关闭')}}</el-button></template></el-dialog></template>
<style scoped>.relation-picker{font-size:12px;min-width:0}.tools{display:flex;gap:8px}.relation-results{max-height:55dvh;overflow:auto;margin:10px 0}.relation-results article{display:flex;gap:12px;justify-content:space-between;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--el-border-color-light)}.relation-results article>div{min-width:0;overflow-wrap:anywhere}.relation-results p{margin:5px 0}.relation-results small{display:block;color:var(--el-text-color-secondary)}.relation-results .el-button{flex:none}@media(max-width:650px){.relation-results article{flex-direction:column}}</style>
